function detectClosedRegions(){const w=workCanvas.width,h=workCanvas.height,im=wctx.getImageData(0,0,w,h).data,raw=new Uint8Array(w*h);for(let p=0,i=0;p<raw.length;p++,i+=4)raw[p]=(im[i]*.299+im[i+1]*.587+im[i+2]*.114)|0;const gray=blurGray(raw,w,h),sens=Number($('sensitivity').value),global=otsu(gray);let dark=adaptiveInk(gray,w,h,sens);for(let i=0;i<dark.length;i++)if(gray[i]<global-18)dark[i]=1;const ink=closeInk(dark,w,h),outside=new Uint8Array(w*h),q=new Int32Array(w*h);let qs=0,qe=0;const push=i=>{if(i>=0&&i<w*h&&!ink[i]&&!outside[i]){outside[i]=1;q[qe++]=i}};for(let x=0;x<w;x++){push(x);push((h-1)*w+x)}for(let y=0;y<h;y++){push(y*w);push(y*w+w-1)}while(qs<qe){const i=q[qs++],x=i%w,y=(i/w)|0;if(x>0)push(i-1);if(x<w-1)push(i+1);if(y>0)push(i-w);if(y<h-1)push(i+w)}const enclosed=new Uint8Array(w*h);for(let i=0;i<enclosed.length;i++)enclosed[i]=(!ink[i]&&!outside[i])?1:0;const comps=componentBoxes(enclosed,w,h,Math.max(90,w*h*.00005),w*h*.22),regions=[];for(const c of comps){const bw=c.maxX-c.minX+1,bh=c.maxY-c.minY+1,area=bw*bh,fill=c.count/area,aspect=bw/bh;if(bw<24||bh<15||area>w*h*.2||aspect>7||aspect<.14||fill<.26)continue;regions.push({...c,cx:(c.minX+c.maxX)/2,cy:(c.minY+c.maxY)/2,score:Math.min(1,.45+fill*.55)})}regions.sort((a,b)=>b.score-a.score);const kept=[];for(const r of regions){if(kept.some(k=>iou(r,k)>.62))continue;kept.push(r)}return{regions:kept.slice(0,60),dark:ink,w,h}}
